def rotate(matrix):
    # Get size of matrix
    n = len(matrix)
    # Step 1: Transpose the matrix
    for i in range(n):
        # Loop starting from i+1 to avoid swapping elements back
        for j in range(i + 1, n):
            # Swap elements across the main diagonal
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]
    # Step 2: Reverse each row of the matrix
    for i in range(n):
        # Reverse current row in-place
        matrix[i].reverse()

