def uniquePaths(m, n):
    # Helper recursive function
    def countPaths(i, j):
        # Reach target
        if i == m - 1 and j == n - 1:
            return 1
        # Out of bounds
        if i >= m or j >= n:
            return 0
        # Move down or move right
        return countPaths(i + 1, j) + countPaths(i, j + 1)
    # Start from top-left
    return countPaths(0, 0)

def uniquePaths(m, n):
    # DP grid initialized with 1
    dp = [[1] * n for _ in range(m)]
    # Iterate through cells
    for i in range(1, m):
        for j in range(1, n):
            # DP transition
            dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
    # Return target cell
    return dp[m - 1][n - 1]

