def reversePairs(nums):
    # Main divide and conquer function
    def merge_sort(left, right):
        if left >= right:
            return 0
        mid = (left + right) // 2
        count = merge_sort(left, mid) + merge_sort(mid + 1, right)
        count += count_pairs(left, mid, right)
        merge(left, mid, right)
        return count

    # Count valid cross-pairs
    def count_pairs(left, mid, right):
        count = 0
        j = mid + 1
        for i in range(left, mid + 1):
            while j <= right and nums[i] > 2 * nums[j]:
                j += 1
            count += (j - (mid + 1))
        return count

    # Merge sorted subdivisions
    def merge(left, mid, right):
        temp = []
        i, j = left, mid + 1
        while i <= mid and j <= right:
            if nums[i] <= nums[j]:
                temp.append(nums[i])
                i += 1
            else:
                temp.append(nums[j])
                j += 1
