            i += 1
        while j <= right:
            temp.append(nums[j])
            j += 1
        for k in range(len(temp)):
            nums[left + k] = temp[k]

    # Start merge sort
    return merge_sort(0, len(nums) - 1)

def fourSum(nums, target):
    # Get size of array
    n = len(nums)
    # Set to record unique results
    res = set()
    # 4 nested loops to check all quadruplets
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                for l in range(k + 1, n):
                    if nums[i] + nums[j] + nums[k] + nums[l] == target:
                        quad = tuple(sorted([nums[i], nums[j], nums[k], nums[l]]))
                        res.add(quad)
    # Return final results converted back to list of lists
    return [list(x) for x in res]

def fourSum(nums, target):
    # Sort array
    nums.sort()
    n = len(nums)
    ans = []
    # Fix first element
    for i in range(n):
        # Skip duplicate first element
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        # Fix second element
        for j in range(i + 1, n):
            # Skip duplicate second element
            if j > i + 1 and nums[j] == nums[j - 1]:
                continue
            # Two pointers
            left = j + 1
            right = n - 1
            while left < right:
                curr_sum = nums[i] + nums[j] + nums[left] + nums[right]
                if curr_sum == target:
                    ans.append([nums[i], nums[j], nums[left], nums[right]])
                    left += 1
                    # Skip duplicate left elements
                    while left < right and nums[left] == nums[left - 1]:
                         left += 1
                    right -= 1
                    # Skip duplicate right elements
                    while left < right and nums[right] == nums[right + 1]:
                         right -= 1
                elif curr_sum < target:
                    left += 1
                else:
                    right -= 1
    # Return results
    return ans

def maxLen(arr):
    # Store first occurrence index of prefix sums
    sum_map = {}
    curr_sum = 0
    max_len = 0
    # Iterate through array elements
    for i in range(len(arr)):
        curr_sum += arr[i]
        # Case 1: Prefix sum is 0
        if curr_sum == 0:
            max_len = i + 1
        # Case 2: Prefix sum seen before
        elif curr_sum in sum_map:
            max_len = max(max_len, i - sum_map[curr_sum])
        # Case 3: Prefix sum is new
        else:
            sum_map[curr_sum] = i
    # Return result
    return max_len
